<div class="page-head"><div><p class="eyebrow">Administration</p><h1>User Management</h1><p>Manage system accounts and permissions. Your own account stays protected.</p></div></div>
<section class="panel"><div class="panel-head"><div><h2><?=$edit?'Edit User':'Add New User'?></h2><span class="panel-sub">Account information and role assignment</span></div></div><form method="post" data-validate-form><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="form-grid"><div class="field"><label>Username</label><input name="username" value="<?=e($edit['username']??'')?>" required minlength="3" maxlength="30" pattern="[A-Za-z0-9_.-]{3,30}"></div><div class="field"><label>Full Name</label><input name="name" value="<?=e($edit['name']??'')?>" required maxlength="100"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?=e($edit['email']??'')?>" required></div><div class="field"><label>Role</label><select name="role" <?=isset($edit['id'])&&$edit['id']===$_SESSION['user']['id']?'disabled':''?>><?php foreach($roles as $r):?><option value="<?=e($r)?>" <?=($edit['role']??'')===$r?'selected':''?>><?=e($r)?></option><?php endforeach;?></select></div><div class="field"><label>Status</label><select name="status" <?=isset($edit['id'])&&$edit['id']===$_SESSION['user']['id']?'disabled':''?>><?php foreach($statuses as $s):?><option value="<?=$s?>" <?=($edit['status']??'Active')===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></div></div><div class="form-actions"><button class="btn"><?=$edit?'✓ Update User':'＋ Add User'?></button><?php if($edit):?><a class="btn gray" href="users.php">Cancel</a><?php endif;?></div><?php if(!$edit):?><p class="helper">New accounts are created with a temporary password and should change it from My Profile.</p><?php endif;?></form></section><br>
<section class="panel"><div class="panel-head"><div><h2>All Users</h2><span class="panel-sub"><?=count($users)?> registered accounts</span></div></div><div class="table-wrap"><table class="table"><tr><th>Username</th><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Joined</th><th>Actions</th></tr><?php foreach($users as $x):?><tr><td><b><?=e($x['username'])?></b><?php if($x['id']==$_SESSION['user']['id']):?> <span class="badge">You</span><?php endif;?></td><td><?=e($x['name'])?></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=$x['status']==='Active'?'<span class="badge green">Active</span>':'<span class="badge gray">Inactive</span>'?></td><td><?=e(date('d M Y',strtotime($x['created_at'])))?></td><td class="actions"><a class="btn small" href="users.php?edit=<?=$x['id']?>">✎ Edit</a><?php if($x['id']!=$_SESSION['user']['id']):?><form method="post" class="inline-form" onsubmit="return confirmDelete('Delete this user permanently?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="delete_id" value="<?=$x['id']?>"><button class="btn small danger" type="submit">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section>
